# sandbox-terraform: the network, EFS volume, IAM role and head node.
# Read by exportit/tools/export.py; described in exportit/MAP.md.
#
# The whole of terraform/ goes to the root of the unit, unchanged: the module,
# the remote-state module, the example settings, the Image Builder sketch and
# the old copies (decision 2 of stage 4).

covers terraform/
copy terraform/    ./

# Files that exist only in the unit.
# Stage 8: DEPLOYMENT.md's Terraform part, written for this unit, and the
# screenshot it shows.
copy images/AWS-Key-pairs-screen.png    docs/images/AWS-Key-pairs-screen.png

new README.md
new DEPLOYMENT.md
new LICENSE                    # a copy of the repository's LICENSE
new Justfile
new pyproject.toml
new uv.lock
new .python-version
new init_template.ansible.tpl  # the first-boot script that runs the Ansible playbooks
new tests/
new tools/                     # fetches the pinned OpenTofu into .tofu/
new versions.tofu              # the OpenTofu version both modules require (read by OpenTofu only)
new remote-state/versions.tofu
new reaper/                  # the zombie-node guard: a root module of its own (spec 003); its functions/ arrived by moved lines in cloudflow.map
new proof/                   # the live proof's override files, copied beside main.tf in its working copy (spec 001)
new build-cache/             # the RHEL 10 build cache's bucket: a root module of its own (spec 002)
new .gitignore   # the unit's own, since it is a repository of its own (MOVINGDAY.md)
new .specify/     # Spec Kit 1.2.3 and the constitution (MOVINGDAY.md, M4)
new .claude/      # Spec Kit's skills
new CLAUDE.md     # written by `just constitution`

# Its originals were deleted from Cloud-Sandbox by stage 22, step 6 (2026-11-19):
# the unit owns its copied files, and only its lineage is checked.
owned
